#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the color codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: LC6000 PRIME display chip (wd) flash day (#435). The human does every hardware step; this wizard runs the
# read-only checks, asks before each write, and stops at the first surprise. Runbook: #431. Research tooling for #418.
# ──────────────────────────────────────────────────────────────────────────

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
WORK="${LC6000_WORK:-$HOME/lc6000}"
STAMP="$(date +%Y%m%d-%H%M%S)"
STOCK_CRC="0x3A7CE2CA"
APP_ADDRESS="0x08008000"; APP_SIZE="0x78000"
SETTINGS_ADDRESS="0x08004000"; SETTINGS_SIZE="0x4000"
# Sectors 8-11, above the image: block B's home (#501), only on the drawn path.
UPPER_ADDRESS="0x08080000"; UPPER_SIZE="0x80000"
# The option bytes, bank 1 (alt 1): read only, on the drawn path, to check protection before step 1.
OPTION_ADDRESS="0x1FFFC000"; OPTION_SIZE="16"
DFU_PATH=""

dfupatch() { python3 -I "$HERE/dfupatch.py" "$@"; }
drawn() { python3 -I "$HERE/drawn_flash.py" "$@"; }

# way_back prints how to get the unit back to stock, then stops the wizard.
way_back() {
  printf '\n'
  warn "Stopping here. Nothing more is sent."
  say "The way back to stock firmware:"
  step "Power the LC6000 off and on. If it runs normally, you're done."
  note "Block B, if it was written, stays at 0x08080000 and is harmless: only block A calls it, and stock never does."
  note "So B written and the owner's image not: the image already on the chip runs as before."
  step "Denon's updater refuses a unit that's running and current. It flashes a chip that's in update mode."
  step "Display chip: if it's still in update mode (dfu-util -l lists it), open Denon's updater now."
  say  "  If it boots a bad image instead, run this wizard again: stage 2 puts it back in update mode."
  step "Top panel chip: hold BACK + FWD + VINYL while powering on, then open Denon's updater (proven 2026-11-19)."
  step "If the display chip never shows up in update mode: stop. That's the ST-Link job (#433)."
  note "Backups and logs from this run are in $WORK."
  exit 1
}

# dfu_paths lists the USB paths of every 0483:df11 device dfu-util sees, one per line.
dfu_paths() {
  dfu-util -l 2>/dev/null | grep -i 'Found DFU: \[0483:df11\]' | sed -E 's/.*path="([^"]*)".*/\1/' | sort -u
}

# enter_update_mode sends the one SysEx to the display chip and waits for it to come back as a DFU device.
enter_update_mode() {
  say "The display chip has no buttons. One MIDI message on its own port restarts it into update mode."
  note "This writes nothing to its firmware, but it stays in update mode until it's flashed or power-cycled."
  if ! "$WORK/enter-update-mode" check; then
    warn "The display's MIDI port isn't there (or there are two). Is the LC6000 on, on a direct cable?"
    way_back
  fi
  confirm "Send the update-mode message to the display chip now?" || way_back
  "$WORK/enter-update-mode" send --yes-enter-update-mode || way_back
  say "Waiting for the chip to come back as a DFU device (up to 20 s)…"
  local tries=0
  until [[ -n "$(dfu_paths)" ]]; do
    tries=$((tries + 1))
    if (( tries > 20 )); then
      warn "No DFU device appeared. The message may not have been accepted."
      way_back
    fi
    sleep 1
  done
  printf '  %s✓%s a DFU device is there\n' "$GREEN" "$RESET"
}

# look lists the DFU devices, insists on exactly one, and remembers its path.
look() {
  local listing="$WORK/dfu-list-$STAMP-$1.txt" count
  dfu-util -l > "$listing" 2>&1 || true
  grep -i 'Found DFU' "$listing" | sed 's/^/    /' || true
  count=$(dfu_paths | grep -c . || true)
  if [[ "$count" != "1" ]]; then
    warn "$count update-mode devices found; exactly one (the display chip) is needed."
    note "Two means the top panel chip is in update mode too. Flashing the display image into it is the main hazard."
    way_back
  fi
  DFU_PATH="$(dfu_paths)"
  printf '  %s✓%s one device, at USB path %s (saved to %s)\n' "$GREEN" "$RESET" "$DFU_PATH" "$listing"
  if ! grep -q '0x08000000' "$listing"; then
    warn "Its memory layout doesn't name internal flash at 0x08000000. That's not what the runbook expects."
    confirm "Go on anyway?" || way_back
  fi
}

# read_app FILE reads the app area back from the chip (read-only).
read_app() {
  dfu-util -p "$DFU_PATH" -a 0 -s "$APP_ADDRESS:$APP_SIZE" -U "$1"
}

# read_upper FILE reads all of the flash above the image, sectors 8-11, back from the chip (read-only).
read_upper() {
  dfu-util -p "$DFU_PATH" -a 0 -s "$UPPER_ADDRESS:$UPPER_SIZE" -U "$1"
}

# read_options FILE reads the option bytes (alt 1, read-only).
read_options() {
  dfu-util -p "$DFU_PATH" -a 1 -s "$OPTION_ADDRESS:$OPTION_SIZE" -U "$1"
}

# flash IMAGE LABEL [AREA] [WORD] writes one .dfu to the display chip, after the typed WORD (FLASH unless named), then
# reads it back and compares. AREA is app (the image, 0x08008000) or upper (block B, 0x08080000); the caller has
# checked the file is one. Only a rewrite of the upper flash names its own word, REWRITE (#468).
flash() {
  local image="$1" label="$2" area="${3:-app}" word="${4:-FLASH}" typed="" readback="$WORK/wd-readback-$STAMP-$2.bin"
  if [[ "$area" == upper ]]; then
    warn "This ERASES and WRITES the display chip's upper flash, from 0x08080000 as far as block B reaches, with:"
  else
    warn "This ERASES and WRITES the display chip's app area (0x08008000-0x0807FFFF) with:"
  fi
  say  "  $image"
  note "The bootloader and the settings sector are not touched. Don't unplug or power off while it runs."
  printf '  %s? Type %s to write it, anything else to stop:%s ' "$YELLOW" "$word" "$RESET"
  read -r typed || true
  [[ -n "$word" && "$typed" == "$word" ]] || way_back
  if ! dfu-util -p "$DFU_PATH" -a 0 -D "$image" 2>&1 | tee "$WORK/flash-$STAMP-$label.log"; then
    warn "dfu-util reported an error. Don't retry blindly."
    way_back
  fi
  say "Reading it back to check (the stock updater never does this)…"
  if [[ "$area" == upper ]]; then
    if ! read_upper "$readback"; then
      warn "The read-back failed, so the write can't be checked."
      way_back
    fi
    if ! drawn upper "$UPPER_DFU" "$readback" | grep -q '^holds'; then
      warn "The upper flash isn't exactly block B. Block A checks B's CRC before calling it, so it stays unused."
      note "Don't flash the owner's image on top of this. Stop, and post the message above on #468."
      way_back
    fi
    printf '  %s✓%s the upper flash holds exactly block B, then erased flash\n' "$GREEN" "$RESET"
    return
  fi
  if ! read_app "$readback"; then
    warn "The read-back failed, so the write can't be checked."
    way_back
  fi
  if ! dfupatch compare "$image" "$readback"; then
    warn "What's on the chip differs from the image. Don't power-cycle into it: flash the stock image again."
    way_back
  fi
  printf '  %s✓%s the chip holds exactly this image\n' "$GREEN" "$RESET"
}

# reboot_check has the human power-cycle, then waits for the display's MIDI port.
reboot_check() {
  step "Power the LC6000 off, wait 5 seconds, power it on. No buttons held."
  pause "Press Enter once it's back on"
  local tries=0
  until "$WORK/enter-update-mode" check >/dev/null 2>&1; do
    tries=$((tries + 1))
    if (( tries > 30 )); then
      warn "The display's MIDI port didn't come back in 30 s."
      if [[ -n "$(dfu_paths)" ]]; then note "It's still in update mode: the bootloader didn't start the app."; fi
      way_back
    fi
    sleep 1
  done
  printf '  %s✓%s the display chip booted: its MIDI port is back\n' "$GREEN" "$RESET"
}

run_wizard() {

TOTAL_STAGES=8
mkdir -p "$WORK"
ENV_FILE="$WORK/flash-day.env"

banner "LC6000 display chip: flash day"

stage "Ready check"
say "Nothing is sent to the LC6000 in this stage."
for tool in dfu-util swiftc python3; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool isn't installed."
    [[ "$tool" == "dfu-util" ]] && say "Install it with: brew install dfu-util"
    exit 1
  fi
done
step "The stock display firmware: jc20_wd_update_00_50_3A7CE2CA.dfu, copied out of Denon's updater"
say  "  (Contents/Resources inside the .app in docs/research/*.dmg) to a folder outside the repo, such as $WORK."
ask STOCK_WD "Path to the stock wd .dfu:"
STOCK_WD="${STOCK_WD/#\~/$HOME}"
if ! dfupatch verify "$STOCK_WD" | tee "$WORK/verify-$STAMP.txt" | grep -q "$STOCK_CRC"; then
  warn "That file didn't verify as the stock 00.50 image ($STOCK_CRC). Stopping before anything is sent."
  exit 1
fi
write_env STOCK_WD "$STOCK_WD"
say "Building the update-mode tool…"
swiftc -O -swift-version 5 "$HERE/enter-update-mode.swift" -o "$WORK/enter-update-mode"
"$WORK/enter-update-mode" selftest
if pgrep -f "ControllerBridge.app/Contents/MacOS" >/dev/null 2>&1; then
  warn "DeckBridge is running. Quit it first: it talks to the display."
  pause "Press Enter once DeckBridge is quit"
fi
step "Quit every other DJ or MIDI app (Syndicate's MIDI, djay, Engine). Do NOT open Denon's updater."
step "LC6000 on a direct cable to the Mac, not a hub. Powered on, running normally."
step "ST-Link probe on the desk, and you know where the debug pads are (#433)."
step "No gig today."
confirm "All of that true?" || exit 1

stage "Enter update mode (display chip)"
enter_update_mode

stage "Look (read-only)"
say "Listing update-mode devices. Nothing is written."
look "first"
pause

stage "Back up (read-only)"
say "Reading the chip's settings sector and its app, into $WORK. Nothing is written."
note "Whether Denon's bootloader allows reading isn't known yet. If it refuses, you'll be asked."
BACKUP_OK=1
dfu-util -p "$DFU_PATH" -a 0 -s "$SETTINGS_ADDRESS:$SETTINGS_SIZE" -U "$WORK/wd-settings-$STAMP.bin" || BACKUP_OK=0
read_app "$WORK/wd-app-$STAMP.bin" || BACKUP_OK=0
if (( BACKUP_OK )); then
  if dfupatch compare "$STOCK_WD" "$WORK/wd-app-$STAMP.bin"; then
    printf '  %s✓%s the chip is on the stock 00.50 image; backups saved\n' "$GREEN" "$RESET"
  else
    warn "The chip's app isn't the stock 00.50 image. Flashing 00.50 would change it. Stopping."
    way_back
  fi
else
  warn "The read failed, so there's no backup and no proof the chip is on 00.50."
  note "The stock image in Denon's updater is still the way back."
  confirm "Go on without a backup?" || way_back
fi
note "Keep these files out of the repo and don't share them: vendor bytes plus your unit's settings."
pause

stage "Stock flash: Denon's own updater"
say "Denon's updater flashes a chip that's in update mode (seen on this unit for the top panel chip)."
say "Letting it do the display's stock flash proves the road in, and the rescue road, with none of our code."
step "Open Denon's updater now (the .app inside docs/research/*.dmg). The display chip is waiting in update mode."
step "Let it run. Watch for a progress bar; expect it to take longer than the top panel's 7-10 s (5x the data)."
step "Don't unplug or power off while it runs. Quit the updater when it says it's done."
USED_DFU_UTIL=0
if confirm "Did the updater flash the display chip (a progress bar, then done)?"; then
  ask UPDATER_SECONDS "About how many seconds did it take?"
  write_env UPDATER_SECONDS "$UPDATER_SECONDS"
else
  warn "The updater didn't flash it (it said current, or didn't find the unit)."
  say "The other road is dfu-util with the same stock file. It reads the chip back afterwards, which Denon's doesn't."
  confirm "Flash the STOCK image with dfu-util now?" || way_back
  if [[ -z "$(dfu_paths)" ]]; then
    warn "The chip isn't in update mode any more."
    way_back
  fi
  flash "$STOCK_WD" "stock"
  USED_DFU_UTIL=1
fi
pause

stage "Power cycle"
if (( USED_DFU_UTIL )); then note "dfu-util doesn't restart the chip: the power cycle does."; fi
reboot_check
say "Check the unit: does the jog display show its usual idle screen?"
confirm "Display looks normal?" || way_back

stage "Patched image (optional)"
say "The stock flash worked. That was the goal for today."
say "A patched image (such as slot 16, #425) is a separate decision. The safe default is to stop here."
if confirm "Go on and flash a PATCHED image now?"; then
  step "Build it first if you haven't: dfupatch.py apply <stock> <patch> <out, outside the repo>."
  ask PATCHED_WD "Path to the patched wd .dfu:"
  PATCHED_WD="${PATCHED_WD/#\~/$HOME}"
  if ! dfupatch verify "$PATCHED_WD" | tee "$WORK/verify-patched-$STAMP.txt"; then
    warn "That file doesn't verify (bad CRCs or not a wd image). Stopping."
    way_back
  fi
  write_env PATCHED_WD "$PATCHED_WD"
  enter_update_mode
  look "patched"
  say "Checking the chip holds the stock image before changing it (read-only)…"
  if read_app "$WORK/wd-before-patch-$STAMP.bin" && dfupatch compare "$STOCK_WD" "$WORK/wd-before-patch-$STAMP.bin"; then
    printf '  %s✓%s the chip holds the stock image\n' "$GREEN" "$RESET"
  else
    warn "Couldn't confirm the chip holds the stock image (the read failed or it differs)."
    confirm "Flash the patched image anyway?" || way_back
  fi
  flash "$PATCHED_WD" "patched"
  reboot_check
  say "Now test the patch (for slot 16: upload to slot 16, then show 16; see #425's checklist)."
  note "A patched image still reports version 00.50, so Denon's updater will call the running unit current."
  note "To go back to stock: run this wizard again (stage 2 puts the chip in update mode, then Denon's updater)."
else
  say "Stopping after the stock flash. Good."
fi
pause

stage "Way back, for the record"
say "If anything looks wrong later:"
step "Denon's updater flashes stock onto a chip that's in update mode, not onto a running, current unit."
step "Display chip: run this wizard again; stage 2 puts it in update mode, stage 5 is Denon's updater."
step "Top panel chip: hold BACK + FWD + VINYL while powering on, then open Denon's updater."
step "If the display chip never shows up in update mode: ST-Link (#433). Don't keep trying USB."
note "Logs, backups and read-backs from today: $WORK"
say "Please note on #435 what happened at each stage: it's the first proof on real hardware."
pause

finish
}

# The drawn flash (#468): `flash-day.sh drawn`. Two writes, each with its own typed word, read back and compared:
# block B at 0x08080000, then the owner's image. No stock flash: the chip must hold the image it runs now.
run_drawn() {

TOTAL_STAGES=8
mkdir -p "$WORK"
ENV_FILE="$WORK/flash-day.env"

banner "LC6000 display chip: the drawn flash"

stage "Ready check (drawn display)"
say "Nothing is sent to the LC6000 in this stage."
for tool in dfu-util swiftc python3; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool isn't installed."
    exit 1
  fi
done
say "Three files, all outside the repo (such as $WORK):"
step "the .dfu the display chip runs now: the stock 00.50 file, or the slot 16 image you flashed (#425)"
step "block B's .dfu, from build_upper_dfu.py with --proof (the README's read-only checks come first)"
step "the owner's image, from build_owner_image.py"
ask CURRENT_WD "Path to the .dfu the chip runs now:"
CURRENT_WD="${CURRENT_WD/#\~/$HOME}"
ask UPPER_DFU "Path to block B's .dfu:"
UPPER_DFU="${UPPER_DFU/#\~/$HOME}"
ask OWNER_DFU "Path to the owner's image .dfu:"
OWNER_DFU="${OWNER_DFU/#\~/$HOME}"
if ! dfupatch verify "$CURRENT_WD" | tee "$WORK/verify-current-$STAMP.txt"; then
  warn "The image the chip runs now doesn't verify. Stopping before anything is sent."
  exit 1
fi
if ! dfupatch verify "$OWNER_DFU" | tee "$WORK/verify-owner-$STAMP.txt"; then
  warn "The owner's image doesn't verify. Stopping before anything is sent."
  exit 1
fi
if ! drawn files "$UPPER_DFU" "$OWNER_DFU"; then
  warn "Those aren't block B and the owner's image in their places. Stopping before anything is sent."
  exit 1
fi
write_env CURRENT_WD "$CURRENT_WD"
write_env UPPER_DFU "$UPPER_DFU"
write_env OWNER_DFU "$OWNER_DFU"
say "Two things no file can show, so they're yours to say:"
step "Block A, in the owner's image, was built with ARM_UPPER_PROVEN=1. Without it, A never reads B (images only)."
step "Block A and block B were built from the same commit (#516). A and B from different ones stay silent together."
confirm "Both true?" || exit 1
say "Building the update-mode tool…"
swiftc -O -swift-version 5 "$HERE/enter-update-mode.swift" -o "$WORK/enter-update-mode"
"$WORK/enter-update-mode" selftest
if pgrep -f "ControllerBridge.app/Contents/MacOS" >/dev/null 2>&1; then
  warn "DeckBridge is running. Quit it first: it talks to the display."
  pause "Press Enter once DeckBridge is quit"
fi
step "Quit every other DJ or MIDI app. Do NOT open Denon's updater."
step "LC6000 on a direct cable to the Mac, not a hub. Powered on, running normally."
step "No gig today."
confirm "All of that true?" || exit 1
# The probe (#433) is its own question (#468): the owner may flash without one, knowingly, never by confirming one.
if confirm "Is an ST-Link probe connected, and can it read the chip (#433)?"; then
  say "With the probe there, a dark display after the flash can still be brought back."
else
  drawn no-probe-risk
  printf '  %s? Type NO PROBE to go on without it, anything else to stop:%s ' "$YELLOW" "$RESET"
  typed=""
  read -r typed || true
  drawn no-probe "$typed" || exit 1
fi

stage "Enter update mode (display chip)"
enter_update_mode

stage "Look (read-only)"
say "Listing update-mode devices. Nothing is written."
look "drawn"
pause

stage "Before (read-only)"
say "Reading the app and the flash above it, into $WORK. Nothing is written."
if read_app "$WORK/wd-app-before-$STAMP.bin" && dfupatch compare "$CURRENT_WD" "$WORK/wd-app-before-$STAMP.bin"; then
  printf '  %s✓%s the chip holds the image it runs now\n' "$GREEN" "$RESET"
else
  warn "Couldn't confirm the chip holds $CURRENT_WD (the read failed or it differs). Stopping."
  way_back
fi
# The owner's image already there, exactly (a rewrite of block B alone, #468): step 2 has nothing to write.
if ! APP_STATE=$(drawn app "$OWNER_DFU" "$WORK/wd-app-before-$STAMP.bin"); then
  warn "The app area couldn't be judged against the owner's image (the line above says why). Stopping."
  way_back
fi
A_DONE=0
if [[ "$APP_STATE" == holds* ]]; then
  A_DONE=1
  printf "  %s✓%s the owner's image is already there, exactly: step 2 will write nothing\n" "$GREEN" "$RESET"
fi
if ! read_options "$WORK/wd-option-bytes-$STAMP.bin"; then
  warn "The option bytes couldn't be read, so the chip's protection can't be checked. Stopping."
  way_back
fi
if ! drawn options "$WORK/wd-option-bytes-$STAMP.bin"; then
  warn "The chip's protection isn't what block B needs (the line above says what). Nothing is written."
  note "Post that line on #468."
  way_back
fi
if ! read_upper "$WORK/wd-upper-before-$STAMP.bin"; then
  warn "The flash above the image couldn't be read: it isn't shown to exist. Block B has nowhere to go."
  way_back
fi
if ! UPPER_STATE=$(drawn upper "$UPPER_DFU" "$WORK/wd-upper-before-$STAMP.bin"); then
  warn "The flash above the image is neither erased, this block B, nor a block B that checks out."
  note "Nothing is written over it. Post the message above on #468."
  way_back
fi
B_DONE=0; B_REPLACE=0
if [[ "$UPPER_STATE" == holds* ]]; then
  B_DONE=1
  printf '  %s✓%s block B is already there, exactly: step 1 is done\n' "$GREEN" "$RESET"
elif [[ "$UPPER_STATE" == replace* ]]; then
  B_REPLACE=1
  say "The flash above the image holds ${UPPER_STATE#replace }."
  note "Step 1 rewrites it with this block B, after you type REWRITE."
else
  printf '  %s✓%s the flash above the image is erased: block B can go there\n' "$GREEN" "$RESET"
fi
note "Keep these reads out of the repo and don't share them: vendor bytes."
pause

stage "Step 1 of 2: block B"
if (( B_DONE )); then
  say "Block B is already there, exactly as in $UPPER_DFU. Nothing to write."
elif (( B_REPLACE )); then
  say "Rewriting the upper flash with this block B. The read just before this one is the check that it's a B."
  say "Until the owner's image is on, the image there now runs as before: a part or an old B is never called."
  REWRITE_DFU="$WORK/wd-upper-rewrite-$STAMP.dfu"
  drawn rewrite "$UPPER_DFU" "$WORK/wd-upper-before-$STAMP.bin" "$REWRITE_DFU" || way_back
  flash "$REWRITE_DFU" "upper" upper REWRITE
else
  say "Block B goes first. With only B on the chip, the image there now runs as before: only block A calls B."
  flash "$UPPER_DFU" "upper" upper
fi
pause

stage "Step 2 of 2: the owner's image"
say "The hooked image, with block A in its padding. Once it's on, A calls B when DeckBridge asks for drawn mode."
if (( A_DONE )); then
  say "The owner's image is already there, exactly as in $OWNER_DFU. Nothing to write: the app area isn't touched."
else
  if [[ -z "$(dfu_paths)" ]]; then
    warn "The chip isn't in update mode any more."
    way_back
  fi
  flash "$OWNER_DFU" "owner" app
fi
pause

stage "Power cycle"
reboot_check
say "With no host talking to it, the display should look exactly like stock."
confirm "Display looks like stock?" || way_back
say "Then open DeckBridge with drawn mode on: after its hello and begin, the deck chip is drawn by our code."
say "Its end (quit DeckBridge) brings back stock images; a power cycle returns to the app."
note "Whatever you see, write it on #468: it's the first drawn frame on real hardware."
pause

stage "Way back, for the record"
say "If anything looks wrong later:"
step "Display chip: run this wizard again (no 'drawn'); stage 2 puts it in update mode, stage 5 is Denon's updater."
step "Restoring Denon's image removes block A with the hook. Block B stays at 0x08080000, unused: only A calls it."
step "Denon's image has no slot 16 (#425). To get it back, use that wizard's last stage, the patched image."
step "If the display chip never shows up in update mode: ST-Link (#433). Don't keep trying USB."
note "Logs and read-backs from today: $WORK"
say "Please note on #468 what happened at each stage."
pause

finish
}

if [[ "${1:-}" == "drawn" ]]; then run_drawn; else run_wizard "$@"; fi; exit
